print '<!doctype html><html><head><meta charset="utf-8"><title>'.dol_escape_htmltag($sop['ref'].' '.$sop['title']).'</title><style>body{font:14px/1.55 Arial,sans-serif;color:#172c3d;max-width:900px;margin:30px auto}header{border-bottom:3px solid #087fa0;padding-bottom:15px}h1{margin:8px 0}h2{color:#075985}section{break-inside:avoid;margin:22px 0}.meta{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.meta div{border:1px solid #ccdce4;padding:8px}.warn{border:2px solid #dc9817;background:#fff8df;padding:12px}.escalate{border-left:5px solid #b4232c;background:#fff0f0;padding:12px}@media print{button{display:none}body{margin:0}}</style></head><body><button onclick="window.print()">Print</button><header><strong>'.dol_escape_htmltag($sop['ref']).' · Revision '.(int)$sop['revision_no'].'</strong><h1>'.dol_escape_htmltag($sop['title']).'</h1>';if($sop['title_ar'])print'<h2 dir="rtl">'.dol_escape_htmltag($sop['title_ar']).'</h2>';print'<p>Effective: '.dol_escape_htmltag($sop['effective_date']?:'Not set').' · Department: '.dol_escape_htmltag($sop['responsible_department']?:'Not assigned').'</p></header><section><h2>When this SOP applies</h2><p>'.nl2br(dol_escape_htmltag($sop['applicability']?:'General procedure')).'</p><div class="meta">';foreach(array('Country'=>$sop['country_code'],'POL'=>$sop['pol'],'POD'=>$sop['pod'],'Line'=>$sop['shipping_line'],'Service'=>$sop['service_type'],'Container'=>$sop['container_type'],'Incoterm'=>$sop['incoterm'],'Cargo'=>$sop['cargo_type'],'Category'=>$sop['category_label'])as$k=>$v)print'<div><small>'.$k.'</small><br><strong>'.dol_escape_htmltag($v?:'All').'</strong></div>';print'</div></section>';
$list=function($title,$value,$ordered=false,$class=''){if(!($items=ShippingSopService::decodeList($value)))return;print'<section class="'.$class.'"><h2>'.$title.'</h2><'.($ordered?'ol':'ul').'>';foreach($items as$i)print'<li>'.nl2br(dol_escape_htmltag($i)).'</li>';print'</'.($ordered?'ol':'ul').'></section>';};$list('Required information',$sop['required_information']);$list('Procedure steps',$sop['procedure_steps'],true);$list('Required documents',$sop['required_documents']);$list('Important warnings',$sop['warnings'],false,'warn');if($sop['escalation_instructions'])print'<section class="escalate"><h2>Escalation instructions</h2><p>'.nl2br(dol_escape_htmltag($sop['escalation_instructions'])).'</p></section>';print'</body></html>';
